package com.phonoodlesramen.actioncenter.ui.theme

import androidx.compose.ui.graphics.vector.ImageVector
import com.phonoodlesramen.actioncenter.guide.ChannelGlyphs

/*
 * The guide's channel glyphs (I1): Material Symbols Rounded, filled, as in Icons.kt (Apache
 * License 2.0; see docs/third-party-notices.md), each copied as is from
 * symbols/web/<name>/materialsymbolsrounded/<name>_fill1_24px.svg. A glyph's name is the
 * symbol's, and [ChannelGlyphs] picks it.
 */

/** The glyph called [name], or null for one this build doesn't know (a newer pick). */
object ChannelGlyphIcons {
    private val cache = HashMap<String, ImageVector>()

    fun of(name: String?): ImageVector? {
        val path = PATHS[name ?: return null] ?: return null
        return synchronized(cache) { cache.getOrPut(name) { symbol(name, path) } }
    }

    /** Every glyph [ChannelGlyphs] can pick, by name. */
    private val PATHS: Map<String, String> = mapOf(
        "movie" to MOVIE_FILL,
        "tv_gen" to TV_GEN_FILL,
        "theaters" to THEATERS_FILL,
        "local_fire_department" to LOCAL_FIRE_DEPARTMENT_FILL,
        "explore" to EXPLORE_FILL,
        "cruelty_free" to CRUELTY_FREE_FILL,
        "toys" to TOYS_FILL,
        "sentiment_very_satisfied" to SENTIMENT_VERY_SATISFIED_FILL,
        "fingerprint" to FINGERPRINT_FILL,
        "public" to PUBLIC_FILL,
        "theater_comedy" to THEATER_COMEDY_FILL,
        "family_restroom" to FAMILY_RESTROOM_FILL,
        "castle" to CASTLE_FILL,
        "history_edu" to HISTORY_EDU_FILL,
        "featured_seasonal_and_gifts" to FEATURED_SEASONAL_AND_GIFTS_FILL,
        "skull" to SKULL_FILL,
        "music_note" to MUSIC_NOTE_FILL,
        "visibility" to VISIBILITY_FILL,
        "favorite" to FAVORITE_FILL,
        "rocket_launch" to ROCKET_LAUNCH_FILL,
        "emoji_events" to EMOJI_EVENTS_FILL,
        "sports_football" to SPORTS_FOOTBALL_FILL,
        "military_tech" to MILITARY_TECH_FILL,
        "landscape" to LANDSCAPE_FILL,
        "newspaper" to NEWSPAPER_FILL,
        "mic" to MIC_FILL,
        "restaurant" to RESTAURANT_FILL,
        "auto_fix_high" to AUTO_FIX_HIGH_FILL,
    )
}

